import { lstatSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import semver from 'semver';
export const DEPENDENCY_FIELDS = [
    'dependencies',
    'optionalDependencies',
    'devDependencies',
    'peerDependencies',
];
const STRIPPED_FIELDS = ['packageManager', 'devEngines'];
const DIST_TAG = /^[a-z][a-z0-9._-]*$/i;
const OVERRIDE_REFERENCE = /^\$[@a-z0-9][a-z0-9._/@-]*$/i;
function isRecord(value) {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
}
export function jsonErrorPosition(err, content) {
    const match = err instanceof Error ? /position (\d+)/.exec(err.message) : null;
    if (!match?.[1])
        return '';
    const before = content.slice(0, Number(match[1]));
    const line = before.split('\n').length;
    const column = before.length - before.lastIndexOf('\n');
    return ` at line ${line}, column ${column}`;
}
export function readPackageJson(docsRoot, { allowSymlink }) {
    const path = join(docsRoot, 'package.json');
    let isSymlink;
    try {
        isSymlink = lstatSync(path).isSymbolicLink();
    }
    catch {
        return {
            diagnostics: [
                {
                    level: 'error',
                    code: 'package-json-missing',
                    message: `No package.json in ${docsRoot}.`,
                },
            ],
        };
    }
    if (isSymlink && !allowSymlink) {
        return {
            diagnostics: [
                {
                    level: 'error',
                    code: 'package-json-symlink',
                    message: 'package.json is a symbolic link. Commit the file itself in the docs folder.',
                },
            ],
        };
    }
    const content = readFileSync(path, 'utf8');
    let parsed;
    try {
        parsed = JSON.parse(content);
    }
    catch (err) {
        return {
            diagnostics: [
                {
                    level: 'error',
                    code: 'package-json-invalid',
                    message: `package.json is not valid JSON${jsonErrorPosition(err, content)}.`,
                },
            ],
        };
    }
    if (!isRecord(parsed)) {
        return {
            diagnostics: [
                { level: 'error', code: 'package-json-invalid', message: 'package.json is not an object.' },
            ],
        };
    }
    return { packageJson: parsed, diagnostics: [] };
}
export function dependencySpecs(packageJson, field) {
    const deps = packageJson[field];
    const out = {};
    if (!isRecord(deps))
        return out;
    for (const [name, spec] of Object.entries(deps))
        if (typeof spec === 'string')
            out[name] = spec;
    return out;
}
export function specProblem(spec) {
    const s = spec.trim();
    if (s.toLowerCase().startsWith('npm:'))
        return 'is an npm alias, which is not supported';
    if (semver.validRange(s) !== null)
        return undefined;
    if (DIST_TAG.test(s))
        return undefined;
    return 'is not a version or version range from a registry';
}
function specError(where, name, spec, problem) {
    return {
        level: 'error',
        code: 'package-spec-unsupported',
        message: `${where} ${name} "${spec}" ${problem}. Only packages published to npm or a private registry are supported.`,
        pkg: name,
    };
}
function overrideProblems(value, path, out) {
    if (typeof value === 'string') {
        const problem = OVERRIDE_REFERENCE.test(value) ? undefined : specProblem(value);
        if (problem)
            out.push(specError('overrides', path, value, problem));
        return;
    }
    if (!isRecord(value))
        return;
    for (const [key, nested] of Object.entries(value)) {
        overrideProblems(nested, key === '.' ? path : `${path} > ${key}`, out);
    }
}
export function validatePackageJson(packageJson) {
    const out = [];
    for (const field of DEPENDENCY_FIELDS) {
        for (const [name, spec] of Object.entries(dependencySpecs(packageJson, field))) {
            const problem = specProblem(spec);
            if (problem)
                out.push(specError(field, name, spec, problem));
        }
    }
    if (isRecord(packageJson.overrides)) {
        for (const [name, value] of Object.entries(packageJson.overrides)) {
            overrideProblems(value, name, out);
        }
    }
    const pnpm = packageJson.pnpm;
    if (isRecord(pnpm)) {
        if (pnpm.patchedDependencies !== undefined) {
            out.push({
                level: 'error',
                code: 'package-patches-unsupported',
                message: 'pnpm.patchedDependencies is not supported. Publish a patched version instead.',
            });
        }
        if (isRecord(pnpm.overrides)) {
            for (const [name, value] of Object.entries(pnpm.overrides)) {
                overrideProblems(value, `pnpm.overrides ${name}`, out);
            }
        }
        if (isRecord(pnpm.packageExtensions)) {
            for (const [target, extension] of Object.entries(pnpm.packageExtensions)) {
                if (!isRecord(extension))
                    continue;
                for (const field of ['dependencies', 'optionalDependencies', 'peerDependencies']) {
                    for (const [name, spec] of Object.entries(dependencySpecs(extension, field))) {
                        const problem = specProblem(spec);
                        if (problem)
                            out.push(specError(`pnpm.packageExtensions ${target}`, name, spec, problem));
                    }
                }
            }
        }
    }
    return out;
}
export function cleanPackageJson(packageJson) {
    const cleaned = {};
    for (const [key, value] of Object.entries(packageJson)) {
        if (!STRIPPED_FIELDS.includes(key))
            cleaned[key] = value;
    }
    return `${JSON.stringify(cleaned, null, 2)}\n`;
}
